{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "It redefines \"bullying\" as an act by a student or school employee that substantially interferes with a victim's educational benefits, opportunities, or performance. For acts on school grounds, sponsored activities, provided equipment, transportation, or official bus stops, the act must physically harm the victim or their property, or knowingly place them in reasonable fear of such harm. For acts occurring off school property or outside sponsored activities, the act must be directed at a victim and create a substantial disruption to the education environment or learning process.",
      "rationale": "Conveys the covered actors, substantial educational interference requirement, covered locations, and distinct harm or disruption conditions."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "The bill defines \"school employee\" to include employees of private schools, public charter schools, other public schools, or local education agencies (LEAs).",
      "rationale": "Includes all four categories of employers covered by the definition."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "It defines a \"victim\" as any student if the act is committed by an employee, or another student if the act is committed by a student.",
      "rationale": "Preserves the distinction between student victims of employee acts and other-student victims of student acts."
    },
    {
      "proposition_id": "P4",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "Does not mention the amendment to Section 49-6-4503(b)(3) adding \"and school employee\" after \"each student.\" Other references to school employees do not convey this separate amendment."
    },
    {
      "proposition_id": "P5",
      "status": "partial",
      "summary_quote": "Additionally, the bill would make teachers or school employees subject to suspension or dismissal if they commit acts of harassment, intimidation, bullying, or cyberbullying.",
      "rationale": "Identifies the covered employees, all four forms of misconduct, and both sanctions, but omits the condition that the employee be found to have committed the act."
    },
    {
      "proposition_id": "P6",
      "status": "partial",
      "summary_quote": "It also adds the commission of such acts in violation of school district policy as a ground for certain actions under Tennessee Code Annotated Section 49-5-501.",
      "rationale": "Conveys the addition concerning misconduct that violates district policy, but does not identify subdivision (7) as the amendment target or limit the policy to one adopted under Title 49, Chapter 6, Part 45."
    },
    {
      "proposition_id": "P7",
      "status": "full",
      "summary_quote": "If passed, these changes would take effect July 1, 2026, and apply to acts committed on or after that date.",
      "rationale": "States both the effective date and the prospective applicability to acts committed on or after that date."
    }
  ]
}
